#!/usr/bin/env bash
# Pristine-vs-patched parity check for the vendored rusty-opus fork.
#
# Decodes the libopus corpus (scripts/corpus/, generated by
# scripts/gen-corpus.mjs) with the pristine 1.2.1 crate and with the
# patched vendored copy, in normal / PLC / FEC modes, and compares the
# decoded PCM bit-for-bit. Also encodes the corpus PCM with both crates
# and compares the packets bit-for-bit (the PVQ code is shared between
# encode and decode, so encode must stay identical too).
#
# The pristine copy lives in /tmp (ephemeral) and is re-created from the
# cargo registry whenever it is missing.
#
# Run: `bash scripts/check-decode-parity.sh`
# Exit 0 = all identical, 1 = any mismatch or build failure.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PRISTINE=/tmp/rusty-opus-pristine
PATCHED="$ROOT/vendor/rusty-opus"
CORPUS="$ROOT/scripts/corpus"
export PATH="$HOME/.cargo/bin:$PATH"

# --- pristine copy -------------------------------------------------------
if [ ! -d "$PRISTINE" ]; then
  SRC=$(ls -d "$HOME"/.cargo/registry/src/*/rusty-opus-1.2.1 | head -1)
  echo "creating pristine copy from $SRC"
  cp -r "$SRC" "$PRISTINE"
  chmod -R u+w "$PRISTINE"
fi
# The parity driver must exist in both copies (idempotent).
cp "$PATCHED/examples/parity-decode.rs" "$PRISTINE/examples/parity-decode.rs"
if ! grep -q 'name = "parity-decode"' "$PRISTINE/Cargo.toml"; then
  python3 - "$PRISTINE/Cargo.toml" <<'PY'
import sys
p = sys.argv[1]
s = open(p).read()
s = s.replace('''[[example]]
name = "analysis_trace"''', '''[[example]]
name = "parity-decode"
path = "examples/parity-decode.rs"

[[example]]
name = "analysis_trace"''', 1)
open(p, 'w').write(s)
PY
fi

# --- corpus ---------------------------------------------------------------
if [ ! -f "$CORPUS/manifest.json" ]; then
  echo "generating corpus..."
  node "$ROOT/scripts/gen-corpus.mjs" >/dev/null
fi

# --- build both drivers ---------------------------------------------------
echo "building pristine driver..."
(cd "$PRISTINE" && cargo build --release --example parity-decode 2>&1 | tail -1)
echo "building patched driver..."
(cd "$PATCHED" && cargo build --release --example parity-decode 2>&1 | tail -1)
PRISTINE_BIN="$PRISTINE/target/release/examples/parity-decode"
PATCHED_BIN="$PATCHED/target/release/examples/parity-decode"

fail=0
check() {
  local label="$1"; shift
  local a b sa sb
  # A driver crash must report FAIL, not kill the whole run (set -e).
  a=$("$PRISTINE_BIN" "$@" 2>/dev/null | sha256sum | cut -d' ' -f1); sa=$?
  b=$("$PATCHED_BIN" "$@" 2>/dev/null | sha256sum | cut -d' ' -f1); sb=$?
  if [ "$sa" -ne 0 ] || [ "$sb" -ne 0 ]; then
    echo "FAIL  $label  (driver exit: pristine $sa, patched $sb)"
    fail=1
  elif [ "$a" = "$b" ]; then
    echo "PASS  $label"
  else
    echo "FAIL  $label  (pristine $a != patched $b)"
    fail=1
  fi
}

# --- decode parity: every config x mode -----------------------------------
for f in "$CORPUS"/packets/*.bin; do
  name=$(basename "$f" .bin)
  rate=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.rate)")
  channels=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.channels)")
  frame=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.frameSize)")
  for mode in normal plc fec; do
    check "decode $name [$mode]" decode --packets "$f" --rate "$rate" --channels "$channels" --frame "$frame" --mode "$mode"
  done
done

# --- encode parity: every config ------------------------------------------
for f in "$CORPUS"/pcm/*.s16; do
  name=$(basename "$f" .s16)
  rate=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.rate)")
  channels=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.channels)")
  frame=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.frameSize)")
  bitrate=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.bitrate)")
  app=$(node -e "const m=require('$CORPUS/manifest.json');const c=m.configs.find(c=>c.name==='$name');console.log(c.app)")
  check "encode $name" encode --pcm "$f" --rate "$rate" --channels "$channels" --frame "$frame" --bitrate "$bitrate" --app "$app"
done

if [ "$fail" -eq 0 ]; then
  echo "ALL PARITY CHECKS PASSED"
else
  echo "PARITY CHECKS FAILED"
  exit 1
fi
